"""CoT continuation authorship with the complete original public receipt history."""
import json
from phiagent.harness import gaia2_public_read_judge_v11 as _previous

for _name in dir(_previous):
    if not _name.startswith('_'):
        globals()[_name] = getattr(_previous, _name)

CONTRACT = 'native_parent_receipt_complete_author_v12'
AUTHOR = 'The supplied native action has executed and its observation is the actual\npublic result. Reason from the full task, returned data, completed action, prior\nnative reasoning and original public receipt. Author a continuation bank covering\nthe useful remaining operations supported by these facts. The bank persists\nacross intervening tool reads and native reasoning; one-token decisions select\neach action separately or abstain. Keep all task filters, exceptions, ordering,\ntiming and authorization in the note and candidate conditions. Never declare\ncompletion, waits, user messages, future observations or invented field names.\nUse exactly the supplied native tool names, argument names and argument types.\nOmit irrelevant optional parameters. Known public values may be literals.\nBindings are objects: {"$obs":["field",0,"id"]} refers to THIS supplied result;\n{"$prev":["offset"]} refers to THIS completed action\'s arguments. They keep\ntheir original public source across intervening reads. An exact earlier query\nmay be referenced by {"$receipt":{"tool":"native tool","arguments":{},\n"path":["field"]}}. Omit arguments only if the latest call of that tool is intended.\nFor an actual observed list, declare foreach with path and where. Object-list\nmembers use {"$item":["actual_field"]}; a list of scalar identifiers uses\n{"$item":[]} with where:{}. A scalar, count, time or object is not a list.\nUse only observed paths and types. An earlier list may use foreach.receipt\nwith its exact native query. Each declared iterator presents its next unissued\nmember for a separate one-token selection; it never executes a batch. Every\nmember is retained in the declared scope. Do not enumerate a long list as\neight arbitrary examples. Missing prerequisites require native CoT; an empty\nbank is correct when no operation can be grounded. Return the supplied schema.\n\nAudit the remaining task against ALL supplied original public tool receipts,\nin their actual chronological order, before authoring the bank. Distinguish\nan operation\'s observed result from an intention, issued request or bank note.\nCarry forward earlier discovered identifiers, recipients, product variants,\nfilters and time constraints. State what remains to be done; do not restart\ncompleted subgoals. A changed observation may warrant another read, while the\nsame earlier evidence alone does not make a completed read newly necessary.\n\nBind arguments to the actual receipt and observed field that supplies them.\nDo not use placeholder identifiers such as PENDING_ITEM_ID, replace a required\nrecipient with an omitted argument, or use a time lookup as a wait. If a needed\nargument, task condition or future reply is unavailable, omit that operation\nand leave interpretation to native CoT. Retain separately justified candidates\nwhose prerequisites are available. For pagination, use the observed collection\nand native schema; do not infer a field or complete coverage from one page.\n\nKeep the note concise and factual so the full bank can finish within the\nunchanged native output capacity. Exact tool arguments and candidate conditions\nmust retain the task\'s ordering, exceptions and authorization. No task answer,\ntest feedback or private environment state is supplied here.'


def author_request(*args, **kwargs):
    body = _previous.author_request(*args, **kwargs)
    body['messages'][0]['content'] = AUTHOR
    state = json.loads(body['messages'][1]['content'])
    state['public_receipt_scope'] = 'Complete original public tool receipt history; no latest-only slice'
    body['messages'][1]['content'] = json.dumps(state, ensure_ascii=False)
    return body
